async ({ http: { request } }) => {
  const r = await request("https://raw.githubusercontent.com/cv/pi-action/main/src/activity.ts", { maxBytes: 400000 });
  const lines = String(r.body).split("\n");
  const idx = lines.map((l, i) => (/@pit|present|label|toolCall\.arguments|args/i.test(l) ? i : -1)).filter((i) => i >= 0);
  const out = new Set<number>();
  for (const i of idx.slice(0, 25)) for (let j = Math.max(0, i - 2); j <= Math.min(lines.length - 1, i + 3); j++) out.add(j);
  return { status: r.status, len: lines.length, text: [...out].sort((a, b) => a - b).map((i) => `${i + 1}: ${lines[i]}`).join("\n").slice(0, 8000) };
}
